from typing import List, Union

class LookupErr:
    def __init__(self, NotFound: str = "", EmptyCollection: bool = False):
        self.NotFound = NotFound
        self.EmptyCollection = EmptyCollection

    def __repr__(self):
        if self.NotFound:
            return f"LookupErr(NotFound='{self.NotFound}')"
        return f"LookupErr(EmptyCollection={self.EmptyCollection})"

def safeInsertAt(arr: List[int], idx: int, val: int) -> Union[List[int], LookupErr]:
    first = arr
    second = idx

    if second < 0:
        return LookupErr(NotFound="Negative index")

    if len(first) == 0:
        if second == 0:
            return [val]
        return LookupErr(EmptyCollection=True)

    if second > len(first):
        return LookupErr(NotFound=f"Index {second} out of bounds")

    result = first.copy()
    result.insert(second, val)
    return result

def main():
    test_cases = [
        ([1, 2, 3], 1, 10),
        ([], 0, 5),
        ([], 1, 5),
        ([4, 5, 6], 3, 7),
        ([4, 5, 6], 4, 7),
        ([1], 0, 0),
        ([1, 2, 3, 4, 5], 2, 99),
        ([10], 1, 20),
        ([], 0, -1),
        ([5, 6, 7], -1, 8),
