        ([1, 2], 2, 3),
        ([100], 0, 200),
        ([], 0, 0),
        ([9, 8, 7], 0, 6)
    ]

    for arr, idx, val in test_cases:
        result = safeInsertAt(arr, idx, val)
        print(result)

if __name__ == "__main__":
    main()

