import java.util.*;

public class Solution {
    public static class LookupErr {
        public final String NotFound;
        public final boolean EmptyCollection;

        private LookupErr(String NotFound, boolean EmptyCollection) {
            this.NotFound = NotFound;
            this.EmptyCollection = EmptyCollection;
        }

        public static LookupErr notFound(String msg) {
            return new LookupErr(msg, false);
        }

        public static LookupErr emptyCollection() {
            return new LookupErr(null, true);
        }

        @Override
        public String toString() {
            if (EmptyCollection) {
                return "LookupErr{EmptyCollection=true}";
            }
            return "LookupErr{NotFound='" + NotFound + "'}";
        }
    }

    public static Object safeInsertAt(long[] arr, long idx, long val) {
        if (arr.length == 0) {
            return LookupErr.emptyCollection();
        }

        if (idx < 0) {
            return LookupErr.notFound("Negative index: " + idx);
        }

        if (idx > arr.length) {
            return LookupErr.notFound("Index " + idx + " exceeds length " + arr.length);
        }

        long[] result = new long[arr.length + 1];
        int index = (int) idx;

        for (int i = 0; i < index; i++) {
            result[i] = arr[i];
        }

        result[index] = val;

        for (int i = index; i < arr.length; i++) {
            result[i + 1] = arr[i];
        }

        return result;
    }

    public static void main(String[] args) {
        // Test 1: Normal insertion
        long[] arr1 = {1, 2, 3, 4};
        Object result1 = safeInsertAt(arr1, 2, 99);
        if (result1 instanceof long[]) {
            System.out.println("Test 1: " + Arrays.toString((long[]) result1));
        } else {
            System.out.println("Test 1: " + result1);
        }

        // Test 2: Insert at beginning
        long[] arr2 = {10, 20, 30};
        Object result2 = safeInsertAt(arr2, 0, 5);
        if (result2 instanceof long[]) {
            System.out.println("Test 2: " + Arrays.toString((long[]) result2));
        } else {
            System.out.println("Test 2: " + result2);
        }

        // Test 3: Insert at end (idx = length)
        long[] arr3 = {100, 200};
        Object result3 = safeInsertAt(arr3, 2, 300);
        if (result3 instanceof long[]) {
            System.out.println("Test 3: " + Arrays.toString((long[]) result3));
        } else {
            System.out.println("Test 3: " + result3);
        }

        // Test 4: Empty array (should return EmptyCollection error)
        long[] arr4 = {};
        Object result4 = safeInsertAt(arr4, 0, 42);
        System.out.println("Test 4: " + result4);

        // Test 5: Index out of bounds (idx > length)
        long[] arr5 = {1, 2, 3};
        Object result5 = safeInsertAt(arr5, 5, 99);
        System.out.println("Test 5: " + result5);

        // Test 6: Negative index
        long[] arr6 = {5, 10, 15};
        Object result6 = safeInsertAt(arr6, -1, 0);
        System.out.println("Test 6: " + result6);

        // Test 7: Insert with zero value
        long[] arr7 = {7, 8, 9};
        Object result7 = safeInsertAt(arr7, 1, 0);
        if (result7 instanceof long[]) {
            System.out.println("Test 7: " + Arrays.toString((long[]) result7));
        } else {
            System.out.println("Test 7: " + result7);
        }
    }
}
